EditorApplication.delayCall+=()=>{try{
if(Application.isPlaying)throw new Exception("Edit mode required");var rows=new List<string>();foreach(var mf in GameObject.Find("Memory loop - north is +Z").GetComponentsInChildren<MeshFilter>()){
if(!AssetDatabase.GetAssetPath(mf.sharedMesh).StartsWith(Racer.Editor.BackyardForwardAuthoring.Folder+"/Ground_"))continue;var mesh=mf.sharedMesh;var vs=mesh.vertices;var cs=mesh.colors;var us=mesh.uv;var rs=new List<Vector4>();mesh.GetUVs(1,rs);var ts=mesh.triangles;var map=new Dictionary<(Vector3Int,Color32),int>();var v=new List<Vector3>();var c=new List<Color>();var u=new List<Vector2>();var r=new List<Vector4>();var remap=new int[vs.Length];for(int i=0;i<vs.Length;i++){var key=(Vector3Int.RoundToInt(vs[i]*10000),(Color32)cs[i]);if(!map.TryGetValue(key,out int n)){n=v.Count;map[key]=n;v.Add(vs[i]);c.Add(cs[i]);u.Add(us[i]);r.Add(rs[i]);}remap[i]=n;}for(int i=0;i<ts.Length;i++)ts[i]=remap[ts[i]];mesh.Clear();mesh.indexFormat=UnityEngine.Rendering.IndexFormat.UInt32;mesh.SetVertices(v);mesh.SetColors(c);mesh.SetUVs(0,u);mesh.SetUVs(1,r);mesh.SetTriangles(ts,0);mesh.RecalculateNormals();mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);mf.GetComponent<MeshCollider>().sharedMesh=null;mf.GetComponent<MeshCollider>().sharedMesh=mesh;rows.Add(mf.name+": "+vs.Length+" -> "+v.Count+" vertices; same triangles/positions within 0.1mm");}
var glass=AssetDatabase.LoadAssetAtPath<Material>("Assets/Resources/VehicleGlazing.mat");glass.SetFloat("_SrcBlend",1);EditorUtility.SetDirty(glass);AssetDatabase.SaveAssets();Physics.SyncTransforms();System.IO.File.WriteAllLines("Docs/BackyardForward/terrain-compaction.txt",rows);
}catch(Exception e){System.IO.File.WriteAllText("Docs/BackyardForward/terrain-compaction-error.txt",e.ToString());}};return "Weld duplicate terrain vertices while preserving actual surface geometry";
